internal struct BackendFailure {
    let kind: SdkErrorCode
    let message: String
    let errorCode: String?
    let traceId: String?

    /// 排障多行文案，与 Core 的 BackendFailure::display_message 同形。
    func diagnostics() -> String {
        var lines = [message]
        if let errorCode, !errorCode.isEmpty { lines.append("errorCode: \(errorCode)") }
        if let traceId, !traceId.isEmpty { lines.append("traceId: \(traceId)") }
        return lines.joined(separator: "\n")
    }

    func toSdkError() -> SdkError { SdkError(code: kind, message: diagnostics()) }
}

